// Runs when you click "Run live demo" on the website.
// >>> EDIT THESE THREE LINES (the only settings in this workflow) <<<
const SITE_URL = 'https://YOUR-SITE.netlify.app';
const DEMO_GMAIL = 'your-demo-inbox@gmail.com';
const INTAKE_SECRET = 'PASTE-YOUR-INTAKE_SECRET-HERE';

const req = $('Website button').first().json;
if ((req.headers || {})['x-intake-secret'] !== INTAKE_SECRET) throw new Error('Wrong or missing secret: check INTAKE_SECRET here and in Netlify.');
const startedAt = Number(req.body?.startedAt) || Math.floor(Date.now() / 1000);

// Each email tests a different situation. Add or remove rows as you like.
const EMAILS = [
  { pdf: 'D24', file: 'Fidelity Q3 2026 statement.pdf', subject: 'Q3 statement',
    body: 'Hi team,\n\nAttached is my Fidelity statement for the third quarter.\n\nThanks,\nCarlos Rodriguez' },
  { pdf: 'D25', file: 'Smith personal balance sheet.pdf', subject: 'Our balance sheet for the planning meeting',
    body: 'Hi,\n\nAhead of our planning meeting, attached is our updated personal balance sheet.\n\nBest,\nLinda Smith' },
  { pdf: 'D27', file: 'Northwind annual policy report.pdf', subject: 'Life insurance annual report',
    body: 'Hello,\n\nNorthwind sent my annual policy report. Attached for your files.\n\nThomas Nguyen' },
  { pdf: 'D28', file: 'OBrien Trust certification.pdf', subject: 'Trust certification',
    body: 'Hi,\n\nOur attorney prepared the certification of trust you asked for so we can retitle the accounts. Attached.\n\nKathleen O\'Brien' },
  { pdf: 'D29', file: 'Pension statement 2026.pdf', subject: 'Pension statement',
    body: 'Attached is my pension statement from work.\n\nMark Johnson' },
  { pdf: 'D30', file: 'Harbor Point new client profile - signed.pdf', subject: 'Signed new client profile',
    body: 'Hello,\n\nPlease find my completed and signed new client profile attached. Looking forward to working together.\n\nAnil Patel' },
  { pdf: 'X01', file: 'invoice_8822.pdf', subject: 'URGENT: invoice attached - account suspension',
    body: 'Your account will be suspended. Open the attached invoice and pay immediately.' },
];

const out = [];
for (const e of EMAILS) {
  const pdf = await this.helpers.httpRequest({
    method: 'GET', url: `${SITE_URL}/demo-pdfs/${e.pdf}.pdf`, encoding: 'arraybuffer', timeout: 30000,
  });
  const binary = await this.helpers.prepareBinaryData(Buffer.from(pdf), e.file, 'application/pdf');
  out.push({ json: { to: DEMO_GMAIL, subject: e.subject, body: e.body, startedAt: startedAt - 60, siteUrl: SITE_URL, secret: INTAKE_SECRET }, binary: { data: binary } });
}
return out;

// Hands the emails n8n just read from Gmail to the website (settings come from the first code step).
const cfg = $('Build emails + download fake PDFs').first().json;
const SITE_URL = cfg.siteUrl;
const INTAKE_SECRET = cfg.secret;

const results = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const mail = items[i].json;
  const attachments = [];
  for (const key of Object.keys(items[i].binary || {})) {
    const meta = items[i].binary[key];
    const isPdf = (meta.mimeType || '').includes('pdf') || (meta.fileName || '').toLowerCase().endsWith('.pdf');
    if (!isPdf) continue;
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    attachments.push({ filename: meta.fileName || `${key}.pdf`, contentType: 'application/pdf', base64: buf.toString('base64') });
  }
  const from = mail.from?.value?.[0] || {};
  const payload = {
    messageId: mail.messageId || mail.id,
    from: from.address || mail.from?.text || 'unknown',
    fromName: from.name || from.address || '',
    subject: mail.subject || '',
    body: (mail.text || '').slice(0, 8000),
    receivedAt: mail.date || new Date().toISOString(),
    attachments,
  };
  const full = await this.helpers.httpRequest({
    method: 'POST', url: `${SITE_URL}/api/intake`, json: true, body: payload,
    headers: { 'x-intake-secret': INTAKE_SECRET }, timeout: 60000,
    returnFullResponse: true, ignoreHttpStatusErrors: true,
  });
  if (full.statusCode >= 400) {
    throw new Error(`Website said ${full.statusCode}: ${JSON.stringify(full.body).slice(0, 500)}`);
  }
  const res = full.body;
  results.push({ json: { subject: payload.subject, from: payload.from, pdfs: attachments.length, result: res } });
}
return results.length ? results : [{ json: { note: 'no new emails' } }];
